#include <stdio.h>
#define MAX 5

int cqueue[MAX];
int front = -1;
int rear = -1;

// Check if circular queue is full: (rear + 1) % MAX == front
int isFull(void) {
    return (rear + 1) % MAX == front;
}

// Check if circular queue is empty: front == -1
int isEmpty(void) {
    return front == -1;
}

// Enqueue: O(1)
void enqueue(int value) {
    if (isFull()) {
        printf("Circular Queue Overflow! Cannot insert %d (Queue is Full).\n", value);
        return;
    }
    if (front == -1) {
        // First element being added
        front = 0;
        rear = 0;
    } else {
        rear = (rear + 1) % MAX; // Circular increment
    }
    cqueue[rear] = value;
    printf("Enqueued %d at index %d (front=%d, rear=%d).\n", value, rear, front, rear);
}

// Dequeue: O(1)
int dequeue(void) {
    if (isEmpty()) {
        printf("Circular Queue Underflow! Queue is empty.\n");
        return -1;
    }
    int item = cqueue[front];
    printf("Dequeued %d from index %d ", item, front);
    if (front == rear) {
        // Queue had only one element, reset to empty
        front = -1;
        rear = -1;
        printf("(Queue is now reset to empty).\n");
    } else {
        front = (front + 1) % MAX; // Circular increment
        printf("(new front=%d, rear=%d).\n", front, rear);
    }
    return item;
}

// Display circular queue: O(n)
void display(void) {
    if (isEmpty()) {
        printf("Circular Queue is empty.\n");
        return;
    }
    printf("Circular Queue elements: ");
    int i = front;
    while (1) {
        printf("[%d]@idx%d ", cqueue[i], i);
        if (i == rear) break;
        i = (i + 1) % MAX;
    }
    printf("\n");
}

int main(void) {
    printf("--- Circular Queue Implementation in C ---\n");
    enqueue(10);
    enqueue(20);
    enqueue(30);
    enqueue(40);
    enqueue(50); // Fills all 5 slots (0 to 4)
    display();

    enqueue(60); // Triggers Overflow

    dequeue();   // Dequeues 10, index 0 becomes free
    dequeue();   // Dequeues 20, index 1 becomes free
    display();

    // Now wrap-around into vacated slots 0 and 1!
    enqueue(60); // Enqueues 60 at index 0
    enqueue(70); // Enqueues 70 at index 1
    display();

    enqueue(80); // Full again! (rear + 1) % 5 == front (2)
    return 0;
}
